eval(__webpack_require__.ts("__webpack_require__.r(__webpack_exports__);\n/* harmony export */ __webpack_require__.d(__webpack_exports__, {\n/* harmony export */   \"default\": () => (__WEBPACK_DEFAULT_EXPORT__)\n/* harmony export */ });\nconst post = {\n    slug: \"memorable-brands-dont-interrupt-give-something-worth-remembering\",\n    title: \"The Most Memorable Brands Don't Interrupt People. They Give Them Something Worth Remembering.\",\n    excerpt: \"Why interruption marketing fades—and how to design moments people keep without being asked.\",\n    date: \"July 29, 2026\",\n    category: \"Marketing\",\n    image: \"/images/blog/blog-45-memorable-brands.png\",\n    metaDescription: \"The most memorable brands don't interrupt—they give something worth remembering. Why interruption fades and how to design value-first brand moments that last.\",\n    content: [\n        {\n            type: \"p\",\n            text: \"Interruption was once a viable business model because attention was cheap and choice was limited. That world is gone. People now carry a device that can escape any ad in half a second—and a nervous system trained to treat most brand speech as noise. Yet teams still brief campaigns as if the main job is to break into someone’s day.\"\n        },\n        {\n            type: \"p\",\n            text: \"The brands people remember rarely win by interrupting harder. They win by giving something worth keeping: a tool, a story, a useful object, a moment of recognition, a feeling of being understood without being hunted. Memory is not the residue of volume. It is the residue of value.\"\n        },\n        {\n            type: \"p\",\n            text: \"This piece is about designing for memory over reach—gift logic, anti-interruption craft, and why “shareable” is a side effect of generosity, not a demand. It connects to [why people rarely share advertisements—they share stories](/blog/people-rarely-share-advertisements-share-stories) and [how to create marketing people choose to photograph](/blog/how-to-create-marketing-people-photograph).\"\n        },\n        {\n            type: \"h2\",\n            text: \"Why interruption fades (even when it “works”)\"\n        },\n        {\n            type: \"p\",\n            text: \"Interruption can still produce short-term metrics. That is why it persists. The problem is the quality of the memory it creates: association with annoyance, avoidance skills, and brand amnesia the moment the incentive ends. You can rent attention and still own nothing in the mind.\"\n        },\n        {\n            type: \"ul\",\n            items: [\n                \"Frequency without distinctiveness teaches people to ignore you more efficiently.\",\n                \"Claims without gifts create scepticism faster than belief.\",\n                \"Reach without residue means you pay again tomorrow for the same strangers.\",\n                \"Forced attention trains the audience to treat your category as a threat.\"\n            ]\n        },\n        {\n            type: \"takeaway\",\n            text: \"If your growth plan depends on people failing to escape you, you do not have a brand strategy. You have an arms race against the mute button. Related: [what founders actually need isn’t more marketing](/blog/founders-actually-need-isnt-more-marketing).\"\n        },\n        {\n            type: \"h2\",\n            text: \"The Gift → Memory → Meaning loop\"\n        },\n        {\n            type: \"p\",\n            text: \"I use a simple loop when reviewing brand moments. It keeps teams honest about whether they are giving or taking.\"\n        },\n        {\n            type: \"table\",\n            headers: [\n                \"Stage\",\n                \"Question\",\n                \"If missing\"\n            ],\n            rows: [\n                [\n                    \"Gift\",\n                    \"What does the person leave with that they did not have?\",\n                    \"You are interrupting, not offering\"\n                ],\n                [\n                    \"Memory\",\n                    \"Would they recall this without your logo as a prompt?\",\n                    \"You are wallpaper\"\n                ],\n                [\n                    \"Meaning\",\n                    \"Does the gift express a true brand promise?\",\n                    \"You are a random nice thing\"\n                ],\n                [\n                    \"Return path\",\n                    \"Is there a dignified next step if they want more?\",\n                    \"You leave value on the table—or you ambush\"\n                ]\n            ]\n        },\n        {\n            type: \"p\",\n            text: \"Gifts can be intangible: clarity, humour, status, relief, competence. They can be tangible: a template, a sample, a map, a seat, a better queue. The form matters less than the felt generosity—and the link to what you actually sell.\"\n        },\n        {\n            type: \"image\",\n            src: \"/images/blog/blog-mid-01.png\",\n            alt: \"Brand moment designed as a useful gift rather than an interruption\"\n        },\n        {\n            type: \"h2\",\n            text: \"Value-first brand moments (practical types)\"\n        },\n        {\n            type: \"h3\",\n            text: \"1. Utility gifts\"\n        },\n        {\n            type: \"p\",\n            text: \"Give people something that helps them do a job related to your category—ideally before you ask for an email. Calculators, checklists, templates, public tools, and clear explainers still outperform cleverness that helps only the brand.\"\n        },\n        {\n            type: \"h3\",\n            text: \"2. Recognition gifts\"\n        },\n        {\n            type: \"p\",\n            text: \"Show people you understand their private frustration so precisely that they feel seen. Recognition is a gift. Generic empathy copy is not. Specificity is the difference between “we care” and “were you in the room?”\"\n        },\n        {\n            type: \"h3\",\n            text: \"3. Cultural gifts\"\n        },\n        {\n            type: \"p\",\n            text: \"Add something to the culture of a place: wit on a street, a temporary convenience, a beautiful object people want to keep. Cultural gifts travel because they make the giver look generous by association. See [your city is the most underrated marketing channel](/blog/your-city-most-underrated-marketing-channel).\"\n        },\n        {\n            type: \"h3\",\n            text: \"4. Story gifts\"\n        },\n        {\n            type: \"p\",\n            text: \"Give a story people can retell without a brand kit. Stories are portable memory. Ads are usually not. If the tale dies when the logo is removed, it was never a story—it was a claim with production value.\"\n        },\n        {\n            type: \"callout\",\n            title: \"Try this\",\n            text: \"Rewrite your campaign brief replacing “message we need to land” with “gift we will leave behind.” If the room goes quiet, you have found the real work. For product-aligned belief, see [the best marketing feels like product design](/blog/best-marketing-feels-like-product-design).\"\n        },\n        {\n            type: \"h2\",\n            text: \"Interruption vs invitation: a comparison\"\n        },\n        {\n            type: \"table\",\n            headers: [\n                \"Interruption habit\",\n                \"Invitation alternative\"\n            ],\n            rows: [\n                [\n                    \"Autoplay with sound\",\n                    \"Silent craft that rewards voluntary sound-on\"\n                ],\n                [\n                    \"Pop-up before value\",\n                    \"Value before ask; ask once, clearly\"\n                ],\n                [\n                    \"Retargeting that stalks\",\n                    \"Remarketing that continues a useful thread\"\n                ],\n                [\n                    \"Hashtag mandates\",\n                    \"Moments people choose to document\"\n                ],\n                [\n                    \"Fear-based urgency\",\n                    \"Real scarcity or none at all\"\n                ]\n            ]\n        },\n        {\n            type: \"p\",\n            text: \"Invitation is not passivity. It is confidence. You design something good enough that people approach. That may produce fewer raw impressions and better downstream economics—higher trust, better retention, lower support load from mismatched expectations.\"\n        },\n        {\n            type: \"takeaway\",\n            text: \"Memorable brands behave like good hosts: they do not corner guests; they make the room worth entering.\"\n        },\n        {\n            type: \"h2\",\n            text: \"Designing memory on purpose\"\n        },\n        {\n            type: \"p\",\n            text: \"Memory prefers distinctiveness, emotion, and repetition with variation—not repetition alone. A single sharp gift repeated across surfaces will beat twelve disconnected interruptions. This is systems thinking applied to brand: one promise, many generous expressions. More on that posture in [why I care more about systems than campaigns](/blog/why-i-care-more-about-systems-than-campaigns).\"\n        },\n        {\n            type: \"ol\",\n            items: [\n                \"Choose one memory you want to own in the category (not ten).\",\n                \"Design three gifts that encode that memory.\",\n                \"Place them where interruption is unnecessary because the context invites pause.\",\n                \"Measure residue: unaided recall, organic mentions, saved assets, return visits—not only reach.\",\n                \"Retire tactics that create reach while destroying liking.\"\n            ]\n        },\n        {\n            type: \"p\",\n            text: \"Physical space helps because it can gift without a feed’s competitive screaming. Digital helps when it gifts utility at the exact moment of need. Hybrid work—street to screen—works when the bridge is respectful; see [why the internet still needs the real world](/blog/why-internet-still-needs-real-world) and [a good street campaign doesn’t end on the street](/blog/good-street-campaign-doesnt-end-on-street).\"\n        },\n        {\n            type: \"h2\",\n            text: \"Exercise: the keep test\"\n        },\n        {\n            type: \"callout\",\n            title: \"Exercise (30 minutes)\",\n            text: \"Show your campaign to five people. Ask: “What would you keep from this—if anything?” Keep means save, screenshot, retell, revisit, or physically take. If the honest answer is “nothing,” you have an interruption dressed as content. Redesign the gift before you buy media.\"\n        },\n        {\n            type: \"h2\",\n            text: \"Budgeting for residue, not noise\"\n        },\n        {\n            type: \"p\",\n            text: \"Memory work often looks underfunded on a media spreadsheet and overperforming in the world. Fund the gift quality first. Amplify second. If you reverse that, you amplify emptiness. For founders under constraint, read [small budgets don’t kill good ideas—predictable ones do](/blog/small-budgets-dont-kill-good-ideas-predictable-ones-do) and [before you spend £10,000 on marketing](/blog/before-spend-10000-marketing-five-questions).\"\n        },\n        {\n            type: \"h2\",\n            text: \"What to read when you are tired of shouting\"\n        },\n        {\n            type: \"p\",\n            text: \"For how ideas travel through social currency and practical value, [Jonah Berger’s work](https://jonahberger.com/) is useful. For attention and humane design, [Nielsen Norman Group](https://www.nngroup.com/) stays sober. For brand as long-term memory system rather than campaign theatre, [Ehrenberg-Bass Institute](https://www.marketingscience.info/) research on mental availability is a corrective to short-termism—use it as discipline, not as an excuse for bland distinctiveness.\"\n        },\n        {\n            type: \"faq\",\n            items: [\n                {\n                    question: \"Does this mean we should never run ads?\",\n                    answer: \"No. It means ads should carry gifts and distinctiveness—not merely volume. Paid can invite. It does not have to ambush.\"\n                },\n                {\n                    question: \"What if our category is low-interest?\",\n                    answer: \"Then interruption is even less effective. Utility and recognition gifts matter more when category passion is low.\"\n                },\n                {\n                    question: \"How do we report this to a board that wants impressions?\",\n                    answer: \"Report residue metrics alongside reach: unaided recall, branded search, organic save/share quality, activation quality. Teach the board what memory looks like in numbers.\"\n                },\n                {\n                    question: \"Isn’t “gift marketing” just content marketing renamed?\",\n                    answer: \"Content can be a gift. Much content is interruption with paragraphs. The test is whether someone would keep it if your logo were smaller.\"\n                }\n            ]\n        },\n        {\n            type: \"h2\",\n            text: \"Give something worth remembering\"\n        },\n        {\n            type: \"p\",\n            text: \"The most memorable brands do not win the interruption contest. They win the keep test. They leave people better equipped, better recognised, or better amused—and somehow that generosity points back to a product promise without needing a hostage situation.\"\n        },\n        {\n            type: \"p\",\n            text: \"At nau, I design marketing as a system of belief and usefulness: less noise, more residue. If your current plan depends on catching people off guard, it may be time to design something they would choose to keep instead.\"\n        },\n        {\n            type: \"cta\",\n            lead: \"Ready to trade interruption for brand moments people actually remember?\",\n            button: \"Talk about your brand system\",\n            href: \"/contact\"\n        }\n    ]\n};\n/* harmony default export */ const __WEBPACK_DEFAULT_EXPORT__ = (post);\n\n\n;\n    // Wrapped in an IIFE to avoid polluting the global scope\n    ;\n    (function () {\n        var _a, _b;\n        // Legacy CSS implementations will `eval` browser code in a Node.js context\n        // to extract CSS. For backwards compatibility, we need to check we're in a\n        // browser context before continuing.\n        if (typeof self !== 'undefined' &&\n            // AMP / No-JS mode does not inject these helpers:\n            '$RefreshHelpers$' in self) {\n            // @ts-ignore __webpack_module__ is global\n            var currentExports = module.exports;\n            // @ts-ignore __webpack_module__ is global\n            var prevSignature = (_b = (_a = module.hot.data) === null || _a === void 0 ? void 0 : _a.prevSignature) !== null && _b !== void 0 ? _b : null;\n            // This cannot happen in MainTemplate because the exports mismatch between\n            // templating and execution.\n            self.$RefreshHelpers$.registerExportsForReactRefresh(currentExports, module.id);\n            // A module can be accepted automatically based on its exports, e.g. when\n            // it is a Refresh Boundary.\n            if (self.$RefreshHelpers$.isReactRefreshBoundary(currentExports)) {\n                // Save the previous exports signature on update so we can compare the boundary\n                // signatures. We avoid saving exports themselves since it causes memory leaks (https://github.com/vercel/next.js/pull/53797)\n                module.hot.dispose(function (data) {\n                    data.prevSignature =\n                        self.$RefreshHelpers$.getRefreshBoundarySignature(currentExports);\n                });\n                // Unconditionally accept an update to this module, we'll check if it's\n                // still a Refresh Boundary later.\n                // @ts-ignore importMeta is replaced in the loader\n                module.hot.accept();\n                // This field is set when the previous version of this module was a\n                // Refresh Boundary, letting us know we need to check for invalidation or\n                // enqueue an update.\n                if (prevSignature !== null) {\n                    // A boundary can become ineligible if its exports are incompatible\n                    // with the previous exports.\n                    //\n                    // For example, if you add/remove/change exports, we'll want to\n                    // re-execute the importing modules, and force those components to\n                    // re-render. Similarly, if you convert a class component to a\n                    // function, we want to invalidate the boundary.\n                    if (self.$RefreshHelpers$.shouldInvalidateReactRefreshBoundary(prevSignature, self.$RefreshHelpers$.getRefreshBoundarySignature(currentExports))) {\n                        module.hot.invalidate();\n                    }\n                    else {\n                        self.$RefreshHelpers$.scheduleUpdate();\n                    }\n                }\n            }\n            else {\n                // Since we just executed the code for the module, it's possible that the\n                // new exports made it ineligible for being a boundary.\n                // We only care about the case when we were _previously_ a boundary,\n                // because we already accepted this update (accidental side effect).\n                var isNoLongerABoundary = prevSignature !== null;\n                if (isNoLongerABoundary) {\n                    module.hot.invalidate();\n                }\n            }\n        }\n    })();\n//# sourceURL=[module]\n//# sourceMappingURL=data:application/json;charset=utf-8;base64,\n//# sourceURL=webpack-internal:///(app-pages-browser)/./src/lib/blog-posts/memorable-brands-dont-interrupt-give-something-worth-remembering.ts\n"));

